      const iid = String((p && p.item_id) || '').replace(/\D/g, ''); const type = String((p && p.type) || 'note').slice(0, 30); const note = String((p && p.note) || '').slice(0, 500);
      if (!iid || !note) throw new Error('SAY: item id and a note are needed');
